/**
 * The console's web fonts, as base64 so this Worker can serve them itself from `/fonts/` with a
 * year-long immutable cache and keep `font-src 'self'` in every page's Content-Security-Policy.
 *
 * These are the same subsets the public site serves for `/b2c-app-builder/` (its
 * `public/fonts/`): Inter 400/500/600 cut to Latin-1 plus punctuation, and a Latin subset of the
 * Archivo variable face (weight axis kept) for headings. Both faces are under the SIL Open Font
 * License 1.1. A base64 string rather than a Data-module import so `node --import tsx` (the
 * integration tests import worker.ts directly) needs no loader for `.woff2`.
 *
 * Regenerate with: `base64 -i <file>.woff2` for each file, from the site repository's copies.
 */
/** inter-b2c-400.woff2, 16220 bytes. */
export const INTER_400 =
  "";
/** inter-b2c-500.woff2, 16640 bytes. */
export const INTER_500 =
  "";
/** inter-b2c-600.woff2, 16728 bytes. */
export const INTER_600 =
  "";
/** archivo-b2c.woff2, 16460 bytes. */
export const ARCHIVO =
  "";

export const FONT_FILES: Readonly<Record<string, string>> = {
  "inter-b2c-400.woff2": INTER_400,
  "inter-b2c-500.woff2": INTER_500,
  "inter-b2c-600.woff2": INTER_600,
  "archivo-b2c.woff2": ARCHIVO,
};

export function isFontPath(pathname: string): boolean {
  return pathname.startsWith("/fonts/") && Object.hasOwn(FONT_FILES, pathname.slice("/fonts/".length));
}

/** `GET /fonts/<file>`. The bytes never change under one name, so a year-long immutable cache is safe. */
export function handleFontRequest(request: Request): Response {
  if (request.method !== "GET" && request.method !== "HEAD") return new Response(null, { status: 405, headers: { Allow: "GET, HEAD" } });
  const name = new URL(request.url).pathname.slice("/fonts/".length);
  const encoded = FONT_FILES[name];
  if (encoded === undefined) return new Response(null, { status: 404 });
  const binary = atob(encoded);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return new Response(request.method === "HEAD" ? null : bytes, {
    headers: {
      "Content-Type": "font/woff2",
      "Content-Length": String(bytes.length),
      "Cache-Control": "public, max-age=31536000, immutable",
      "Access-Control-Allow-Origin": "https://app.clueless-creations.com",
    },
  });
}
